SELECT sku, product_name, pack_size, flow_type, selling_price_inr, cost_price_inr, units_per_case, case_weight_kg, gtin
FROM store.products
WHERE pack_size ILIKE '%5 kg%' OR product_name ILIKE '%atta%';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'products';

SELECT sku, name, pack, flow, price_inr, cost_inr, case_units, case_kg, gtin
FROM store.products
WHERE pack ILIKE '%5 kg%' OR name ILIKE '%atta%';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'daily_sales';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'shelf_audits';

SELECT SUM(units_sold) as total_units_sold
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-01' AND date <= '2026-06-30';

SELECT table_name
FROM information_schema.tables
WHERE table_schema = 'store';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'inventory_book';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'write_offs';
